{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a nonempty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("required_symbols must be unique")

    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a nonempty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(node["symbol"], str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be a boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id or parent == node["id"]:
            raise ValueError("invalid parent reference")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("node depth does not match parent")
        children[parent].append(node["id"])

    for node in nodes:
        current = node["id"]
        seen = set()
        while current != root_id:
            if current in seen:
                raise ValueError("tree contains a cycle")
            seen.add(current)
            parent = by_id[current]["parent"]
            if parent is None:
                raise ValueError("tree is disconnected")
            current = parent

    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required_symbols):
        raise ValueError("a required symbol is not represented")

    retained = set(by_id)
    retained_child_counts = {node_id: len(child_ids) for node_id, child_ids in children.items()}
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required_symbols:
            continue
        if retained_child_counts[node_id] != 0:
            continue
        if symbol_counts[symbol] <= 0:
            raise ValueError("invalid symbol accounting")
        if symbol in required_symbols and symbol_counts[symbol] <= 1:
            continue
        retained.remove(node_id)
        removed.append(node_id)
        symbol_counts[symbol] -= 1
        parent = node["parent"]
        if parent is not None:
            retained_child_counts[parent] -= 1

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
